    function [guess]=init_pso(n,Lb,Ub)
    ndim=length(Lb);
    for i=1:n,
           guess(i,1:ndim)=Lb+rand(1,ndim).*(Ub-Lb);
    end
    function ns=pso_move(best,gbest,alpha,beta,Lb,Ub)
    n=size(best,1); ndim=size(best,2);
